raw = p.stdout.strip()
if raw.startswith("event:"):
    raw = "\n".join(l[6:].strip() for l in raw.splitlines() if l.startswith("data:"))
try:
    obj = json.loads(raw)
except Exception:
    return {"raw": raw[:3000], "err": p.stderr[:500]}
if "error" in obj:
    return obj["error"]
content = obj.get("result",{}).get("content",[])
texts = [c.get("text","") for c in content if c.get("type")=="text"]
out = "\n".join(texts)
try:
    return json.loads(out)
except Exception:
    return out

